(function () {
  'use strict';
  const C = HUB_CONEXAO_CORE, S = HUB_CONEXAO_STORE, G = HUB_CONEXAO_SUGGESTIONS, X = HUB_CONEXAO_EXTRAS, W = HUB_CONEXAO_CONDUCAO;
  const E = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const D = v => C.date(v) ? String(v).slice(0, 10).split('-').reverse().join('/') : '—';
  const currentTime = () => new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());
  const label = { apto: 'Na janela', atrasado: 'Prazo ultrapassado', proximo: 'Próximo', futuro: 'Futuro', recuperacao: 'Recuperação inicial', realizado: 'Realizado', agendado: 'Agendado', reagendar: 'Reagendar', verificar: 'Sem registro de encontro', convocar: 'A convocar' };
  const badge = (value, text) => `<span class="cx-chip ${E(value)}">${E(text || label[value] || value)}</span>`;
  const option = (v, name, chosen) => `<option value="${E(v)}" ${String(v) === String(chosen) ? 'selected' : ''}>${E(name)}</option>`;
  let el, model, saved, account, modal, toastTimer;
  let sharedFilters = {};
  let npsStamp='';
  function helpSummary(){const summary={overview:'Acompanhe os colaboradores por marco, consulte a ficha e organize turmas. O NPS resume as respostas dos encontros realizados no período dos filtros.',sessions:'Uma turma por cartão, da agenda à devolutiva. Clique no título para consultar participantes, conduzir o roteiro, revisar o relatório, agendar comitês e acompanhar NPS e ações.',actions:'Finalize a condução na turma, revise o relatório coletivo, agende o comitê com RH/DHO, T&D e gestão regional e acompanhe as ações e a devolutiva aos colaboradores.',settings:'Configure os marcos, as janelas antes e depois de cada etapa, o limite de elegibilidade, a capacidade e a duração das turmas.'};return summary[state.tab]||summary.overview;}
  const extraContext=()=>({model,saved,filters:sharedFilters,dialog,toast,onRefresh:()=>{render();updatePersonNps();}});
  const workflowContext=()=>({model,filters:sharedFilters,read:()=>S.read(),dialog,toast,save,refresh:()=>render(),id:S.id,userName:HUB_USER.nome||HUB_USER.email||'',nps:(session,npsDialog)=>X.openNps(session,{...extraContext(),...(npsDialog?{dialog:npsDialog}:{})}),npsSummary:session=>X.session(session),editSession:session=>sessionForm(session),cancelSession:id=>confirmCancel(id),communication:session=>communication(session)});
  function updatePersonNps(){document.querySelectorAll('[data-cx-nps-stage]').forEach(box=>{box.innerHTML=X.personal(box.dataset.cxNpsEmployee,Number(box.dataset.cxNpsStage));});}
  function refreshNps(force=false){const stamp=account+':'+(saved.savedAt||'initial');if(!force&&npsStamp===stamp)return;npsStamp=stamp;X.refresh(extraContext()).then(()=>{if(npsStamp===stamp){render();updatePersonNps();}}).catch(()=>{if(npsStamp===stamp)render();});}
  let state = { tab: 'overview', search: '', unit: '', department: '', manager: '', milestone: '', timing: '', operation: '', focusSession: null, reference: C.today(), all: false, page: 1, selected: new Set() };
  function canRead() { return window.HUB_USER && (HUB_PERMISSIONS.hasPerm(HUB_USER, 'conexao_rh.acompanhar')); }
  function toast(message) { document.querySelector('.cx-toast')?.remove(); const node = document.createElement('div'); node.className = 'cx-toast'; node.setAttribute('role', 'status'); node.textContent = message; document.body.append(node); clearTimeout(toastTimer); toastTimer = setTimeout(() => node.remove(), 6500); }
  async function save(fn) { if(!HUB_PERMISSIONS.hasPerm(HUB_USER,'conexao_rh.gerir')&&!HUB_PERMISSIONS.hasPerm(HUB_USER,'conexao_rh.configurar')){toast('Seu perfil permite apenas consulta.');return false;}try { await S.mutate(fn); modal?.markTurmaSaved?.(); return true; } catch (error) { toast(error.message); return false; } }
  function rebuild() { saved = S.read(); model = C.build(window.HUB_DATA?.colaboradores || [], saved.config, state.reference, saved.events, saved.sessions); }
  function render(target, filters) {
    if (target) el = target;
    if (filters && JSON.stringify(filters) !== JSON.stringify(sharedFilters)) { sharedFilters = { ...filters }; state.page = 1; state.selected.clear(); }
    state.reference = C.today();
    if (!el) return;
    if (!canRead()) { el.innerHTML = '<div class="cx-empty">Acesso ao Conexão RH não liberado para este perfil.</div>'; return; }
    if (!S.ready()) { el.innerHTML='<div class="cx-empty">Carregando registros compartilhados…</div>'; S.load().then(()=>render()).catch(error=>{el.innerHTML='<div class="cx-error">'+E(error.message)+'</div>';}); return; }
    if (account !== HUB_USER.id) { state.selected.clear(); account = HUB_USER.id; }
    try { rebuild(); } catch (error) { el.innerHTML = `<div class="cx-error">${E(error.message)}</div>`; return; }
    const active = document.activeElement, focus = active?.dataset?.cxFilter, position = active?.selectionStart;
    el.innerHTML = `<div class="cx"><header class="cx-hero"><div><div class="cx-eyebrow">Gente & Gestão / Conexão RH</div><h1>Conexões que acompanham a jornada</h1><p>A pessoa certa, no encontro certo. Organize a escuta, acompanhe cada marco e dê continuidade ao que foi combinado.</p></div><div class="cx-orbit" aria-hidden="true">◎</div></header>
      <div class="cx-row"><span class="cx-muted">Fonte: colaboradores integrados ao Hub Sfera · ${model.employees.length} vínculos no quadro acessível (Ativo/Desativado)</span><span class="cx-chip">Registros compartilhados no Hub</span></div>
      <nav class="cx-tabs" role="tablist" aria-label="Conexão RH">${[['overview','Acompanhamento'],['sessions','Turmas e jornada'],['settings','Regras do programa']].map(([v,t])=>`<button type="button" role="tab" aria-selected="${state.tab === v}" data-cx-tab="${v}">${t}</button>`).join('')}</nav>
      <div class="cx-help-row"><div class="cx-help-trigger"><button type="button" class="cx-btn secondary" data-cx-help aria-label="Entenda esta aba do Conexão RH" aria-describedby="cx-help-summary">ⓘ Entenda esta aba</button><div class="cx-help-tooltip" id="cx-help-summary" role="tooltip"><div class="cx-help-tooltip-body"><strong>Resumo da aba</strong><p>${E(helpSummary())}</p><span>Clique para ver a explicação completa e os exemplos.</span></div></div></div></div>
      ${state.tab === 'overview' ? overview() + X.overview(extraContext()) + people() : state.tab === 'sessions' ? sessions() + actions() : settingsView()}
      <p class="cx-legend">Registros compartilhados conforme as permissões do Hub. Convites devem ser enviados pelos responsáveis. Registre somente informações necessárias ao acompanhamento.</p></div>`;
    el.onclick = click; el.onchange = change; el.oninput = event => { if (event.target.dataset.cxFilter === 'search') change(event); };
    const helpTrigger=el.querySelector('.cx-help-trigger');
    helpTrigger.onmouseleave=()=>delete helpTrigger.dataset.dismissed;
    helpTrigger.onfocusout=event=>{if(!helpTrigger.contains(event.relatedTarget))delete helpTrigger.dataset.dismissed;};
    helpTrigger.onkeydown=event=>{if(event.key==='Escape')helpTrigger.dataset.dismissed='true';};
    if(!HUB_PERMISSIONS.hasPerm(HUB_USER,'conexao_rh.gerir'))el.querySelectorAll('[data-cx-suggest],[data-cx-create],[data-cx-new-action],[data-cx-toggle-action]').forEach(b=>{b.disabled=true;b.title='Seu perfil permite apenas consulta';});
    if(state.tab==='settings'&&!HUB_PERMISSIONS.hasPerm(HUB_USER,'conexao_rh.configurar'))el.querySelectorAll('form input,form button').forEach(b=>b.disabled=true);
    if (focus) { const input = el.querySelector(`[data-cx-filter="${focus}"]`); input?.focus(); if (typeof position === 'number' && input?.setSelectionRange && input.type === 'text') input.setSelectionRange(position, position); }
    refreshNps();
  }
  function scopeStages() { return C.launchQueue(model, sharedFilters).queue.filter(s => (!state.milestone || s.milestone === +state.milestone) && (!state.search || C.norm([s.employee.name,s.employee.role,s.employee.department,s.employee.manager].join(' ')).includes(C.norm(state.search)))); }
  function peopleScope() { return model.employees.filter(e => C.matchesEmployee(e, sharedFilters)); }
  function scopedSessions() { return C.scopeSessions(saved.sessions, model.employees, sharedFilters).visible; }
  function scopedActions() { const keys = new Set(peopleScope().map(e=>e.key)); const narrowed = !!(sharedFilters.unidade?.length || sharedFilters.departamento?.length || sharedFilters.gestor || sharedFilters.colaborador); return saved.actions.filter(a => C.inPeriod(a.due, sharedFilters) && (!narrowed || (a.session && saved.sessions.find(s=>s.id===a.session)?.participants.some(k=>keys.has(k))))); }
  function filtered() { return scopeStages().filter(s => (!state.timing || (s.timing === state.timing)) && (!state.operation || s.operation === state.operation)).sort((a,b) => b.employee.admission.localeCompare(a.employee.admission) || a.employee.name.localeCompare(b.employee.name)); }
  function overview() {
    const rows = scopeStages(), pending = rows.filter(s=>!s.completed), due = pending.filter(s=>s.timing==='apto'), soon = pending.filter(s=>s.timing==='proximo');
    const kpi = (value,title,small,filter)=>`<button class="cx-kpi" data-cx-quick="${filter}">${title}<strong>${value}</strong><small>${small}</small></button>`;
    const units = [...new Set(rows.map(s=>s.employee.unit))].sort();
    return `<div class="cx-kpis">${kpi(new Set(rows.map(s=>s.employee.key)).size,'Colaboradores no recorte','Pessoas distintas · período selecionado','')}${kpi(due.length,'Na janela de atendimento','Etapas calculadas sem realização','apto')}${kpi(soon.length,'Próximas etapas',`Janela começa em até ${saved.config.upcoming} dias`,'proximo')}</div>
      <div class="cx-split"><section class="cx-panel"><h2>Distribuição dos elegíveis por marco</h2><p class="cx-muted">Marcos propostos: ${saved.config.milestones.join(', ')} dias. Ajuste as regras antes do piloto.</p>${saved.config.milestones.map(n=>{const total=rows.filter(s=>s.milestone===n).length,done=total;return `<div class="cx-row"><span>${n} dias</span><span class="cx-muted">${total} colaboradores atribuídos</span></div><div class="cx-progress"><span style="width:${rows.length?total/rows.length*100:0}%"></span></div>`;}).join('')}</section><section class="cx-panel"><h2>Distribuição por operação</h2><p class="cx-muted">Pessoas distintas no período e recorte selecionados.</p>${units.slice(0,7).map(u=>`<div class="cx-row" style="margin:12px 0"><span>${E(u)}</span><strong>${new Set(rows.filter(s=>s.employee.unit===u).map(s=>s.employee.key)).size}</strong></div>`).join('') || '<p class="cx-muted">Aguardando a leitura da base integrada.</p>'}${units.length>7?`<p class="cx-muted">Mais ${units.length-7} operações disponíveis nos filtros.</p>`:''}</section></div>`;
  }
  function people() {
    const list = filtered(), pages = Math.max(1,Math.ceil(list.length/40)); state.page=Math.min(state.page,pages);
    const select = (field,title,values)=>`<label class="cx-field">${title}<select data-cx-filter="${field}">${option('','Todos',state[field])}${values.map(v=>option(v,v,state[field])).join('')}</select></label>`;
    const updates = model.employees.map(e=>e.updated).filter(Boolean).sort();
    return `<section class="cx-panel" id="cx-people"><div class="cx-row"><div><h2>Quem vamos acompanhar?</h2><p class="cx-muted">Uma linha por colaborador · admissão mais recente primeiro · tempo de empresa calculado em ${D(state.reference)}. ${updates.length?'Última atualização de registro na base: '+D(updates.at(-1))+'.':'Data de atualização da base não informada.'}</p></div><div><button class="cx-btn secondary" data-cx-suggest>Sugerir turmas</button> <button class="cx-btn" data-cx-new-session>Criar turma manual (${state.selected.size})</button></div></div>
      <div class="cx-note">Implantação em ${D(saved.config.launchDate)}: quem tinha até 120 dias de empresa inicia pelo marco de 30 dias; de 121 a ${saved.config.maxEligibleAge} dias, pelo marco final. A faixa inicial de 30 dias acima da janela comum pode ser agendada até o limite de elegibilidade. Janelas de ${saved.config.before} dias antes e ${saved.config.after} depois. Marcos anteriores à entrada no programa não geram pendências retroativas. ${saved.config.initialRecovery?'Quem tinha entre '+(Math.max(...saved.config.milestones)+saved.config.after+1)+' e '+saved.config.maxEligibleAge+' dias na implantação entra no marco final como recuperação inicial.':''} O período da barra considera janelas que cruzam o intervalo selecionado. Turmas criadas antes desta regra continuam na agenda; revise as que foram montadas para marcos anteriores à entrada. ${C.launchQueue(model,sharedFilters).excluded.filter(x=>x.employee.age>saved.config.maxEligibleAge).length} colaboradores do recorte fora da elegibilidade por ultrapassar ${saved.config.maxEligibleAge} dias.</div>
      ${updates.length&&C.days(C.date(updates.at(-1)),C.today())>7?'<div class="cx-note cx-warning">Há mais de sete dias sem atualização de registro nesta base. Confirme a atualidade dos vínculos antes de convocar participantes.</div>':''}
      <div class="cx-toolbar"><label class="cx-field cx-search">Buscar colaborador, loja ou gestor<input type="text" data-cx-filter="search" value="${E(state.search)}" placeholder="Pesquisar na base do hub"></label></div>
      <div class="cx-toolbar">${select('milestone','Marco',saved.config.milestones)}<label class="cx-field">Prazo<select data-cx-filter="timing">${option('','Todos',state.timing)}${['apto','proximo','futuro','atrasado'].map(v=>option(v,label[v],state.timing)).join('')}</select></label><label class="cx-field">Acompanhamento<select data-cx-filter="operation">${option('','Todos',state.operation)}${['convocar','agendado','realizado','reagendar'].map(v=>option(v,label[v],state.operation)).join('')}</select></label><button class="cx-btn secondary" data-cx-clear>Limpar filtros do módulo</button></div>
      <div class="cx-row"><span class="cx-muted">Período da barra do hub: ${D(sharedFilters.start)} a ${D(sharedFilters.end)} · interseção com a janela do marco atribuído</span><span class="cx-muted">${list.length} colaboradores elegíveis · ${state.selected.size} selecionadas</span></div>
      <div class="cx-table-wrap"><table class="cx-table"><thead><tr><th>Turma</th><th>Colaborador</th><th>Operação / loja</th><th>Admissão</th><th>Marco</th><th>Janela prevista</th><th>Prazo / acompanhamento</th></tr></thead><tbody>${list.slice((state.page-1)*40,state.page*40).map(s=>`<tr><td><input type="checkbox" aria-label="Selecionar ${E(s.employee.name)} no marco ${s.milestone}" data-cx-select="${E(s.key)}" ${state.selected.has(s.key)?'checked':''} ></td><td><button class="cx-name" data-cx-person="${E(s.employee.key)}">${E(s.employee.name)}</button><small>${E(s.employee.role)} · ${s.employee.age} dias</small>${!s.employee.available?'<small>Desativado no hub · conferir disponibilidade</small>':''}</td><td>${E(s.employee.unit)}<small>${E(s.employee.department)}</small></td><td>${D(s.employee.admission)}</td><td><strong>${s.milestone} dias</strong><small>${s.daysToTarget>0?'Faltam '+s.daysToTarget+' dias':s.daysToTarget<0?Math.abs(s.daysToTarget)+' dias após o marco':'Marco hoje'}</small>${s.initialThirty?badge('proximo','Entrada inicial · 30 dias'):s.initialRecovery?badge('proximo','Recuperação inicial'):''}</td><td>${D(s.initialRecovery||s.initialThirty?s.start:s.originalStart)} a ${D(s.initialRecovery||s.initialThirty?s.end:s.originalEnd)}<small>Alvo: ${D(s.target)}</small><small>No programa a partir de ${D(s.start)}</small></td><td>${badge(s.timing)}<small>${badge(s.operation)}</small>${s.scheduled?`<button class="cx-session-link" data-cx-open-session="${E(s.scheduled.id)}">Turma de ${s.scheduled.milestone} dias · ${D(s.scheduled.date)} às ${E(s.scheduled.time)}</button>`:''}${s.previousSession?'<small class="cx-inline-error">Turma anterior de '+s.previousSession.milestone+' dias: revisar na agenda</small>':''}</td></tr>`).join('') || '<tr><td colspan="7"><div class="cx-empty"><strong>Nenhuma etapa neste recorte</strong>Confira os filtros ou aguarde o carregamento dos colaboradores pelo hub.</div></td></tr>'}</tbody></table></div>
      <div class="cx-row" style="margin-top:16px"><span class="cx-muted">Página ${state.page} de ${pages}</span><div><button class="cx-btn secondary" data-cx-page="-1" ${state.page===1?'disabled':''}>Anterior</button> <button class="cx-btn secondary" data-cx-page="1" ${state.page===pages?'disabled':''}>Próxima</button></div></div></section>`;
  }
  function sessions() { return W.board(workflowContext()); }
  function actions() {
    const list = scopedActions().filter(a=>!a.session);
    return `<details class="cx-panel cx-general-actions"><summary>Ações gerais de apoio · ${list.length}</summary><section><div class="cx-row"><div><h2>Plano de ação e acompanhamento</h2><p class="cx-muted">Período da barra do hub aplicado ao prazo da ação; os demais filtros consideram os participantes da turma de origem. Registre somente informações adequadas ao acompanhamento compartilhado.</p></div><button class="cx-btn" data-cx-new-action>Nova ação</button></div>${list.length?`<div class="cx-table-wrap"><table class="cx-table"><thead><tr><th>Ação</th><th>Responsável</th><th>Prazo</th><th>Status</th><th>Próximo passo</th></tr></thead><tbody>${list.map(a=>`<tr><td>${E(a.title)}<small>${a.session?'Turma: '+D(saved.sessions.find(s=>s.id===a.session)?.date):'Ação geral'}</small></td><td>${E(a.owner)}</td><td>${D(a.due)}${!a.done&&a.due<C.today()?'<small class="cx-inline-error">Prazo vencido</small>':''}</td><td>${badge(a.done?'realizado':'Pendente',a.done?'Concluída':'Pendente')}</td><td><button class="cx-btn secondary" data-cx-toggle-action="${a.id}">${a.done?'Reabrir':'Concluir'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="cx-empty"><strong>Nenhuma ação registrada no Conexão RH</strong>As ações de cada turma ficam dentro dela. Aqui ficam os compromissos gerais de apoio ao programa.</div>'}</section></details>`;
  }
  function settingsView() {
    return `<section class="cx-panel cx-settings"><h2>Regras do programa</h2><p class="cx-muted">Marcos configurados: ${saved.config.milestones.join(' / ')} dias. Alterações são compartilhadas com a equipe autorizada. Registros antigos de encontros preservam seu marco original.</p><div class="cx-note">Implantação com janela de ${saved.config.before} dias antes e ${saved.config.after} dias depois de cada marco, e limite de ${saved.config.maxEligibleAge} dias de empresa. Cada colaborador aparece apenas no marco de entrada ou no próximo marco após a participação registrada. A fila considera janelas que cruzam o período da barra do hub. A data-alvo usa a admissão do vínculo. A participação do Conexão ainda precisa de histórico próprio.</div><form data-cx-settings><label class="cx-field">Início do programa<input type="date" name="launchDate" value="${E(saved.config.launchDate)}" required></label><label class="cx-muted"><input type="checkbox" name="initialRecovery" ${saved.config.initialRecovery?'checked':''}> Recuperação inicial no marco final até o limite de elegibilidade</label><div class="cx-toolbar"><label class="cx-field">Marcos em dias, separados por vírgula<input name="milestones" value="${saved.config.milestones.join(', ')}" required></label>${[['before','Antecipação (dias)'],['after','Tolerância (dias)'],['upcoming','Antecedência da lista (dias)'],['maxEligibleAge','Limite de elegibilidade (dias)'],['capacity','Capacidade da turma'],['duration','Duração padrão (min)']].map(([key,title])=>`<label class="cx-field">${title}<input type="number" name="${key}" value="${saved.config[key]}" min="${['capacity','duration','maxEligibleAge'].includes(key)?1:0}" max="1000" required></label>`).join('')}</div><p class="cx-muted">Antecipação abre a janela antes do marco; tolerância fecha a janela depois; antecedência da lista apenas sinaliza “Próximo” antes da abertura. <button type="button" class="cx-help-inline" data-cx-help>Ver explicação e exemplo</button></p><div class="cx-error" data-cx-settings-error role="alert"></div><button class="cx-btn" type="submit">Salvar regras</button></form>${HUB_PERMISSIONS.hasPerm(HUB_USER,"conexao_rh.configurar")?'<p><button type="button" class="cx-btn secondary" data-cx-import-pilot>Importar turmas do piloto</button></p>':""}<h3 style="margin-top:25px">Roteiros de referência</h3><p class="cx-muted">30 dias: acolhimento, clareza, integração e apoio.<br>75 dias: desafios, recursos e relacionamento com a gestão.<br>120 dias: evolução, desenvolvimento e perspectivas de carreira.<br>Convite: sete dias de antecedência. Síntese: 48h após a sessão. Devolutiva: até 15 dias, com prazo próprio para cada ação.</p><div class="cx-note">Este módulo não registra diagnósticos, relatos sensíveis, pontuação automática de risco ou gravações. As regras e os materiais oficiais precisam da validação do DHO antes da publicação.</div></section>`;
  }
  function change(event) {
    const t=event.target;
    if (t.dataset.cxFilter) { const field=t.dataset.cxFilter;if(field==='reference'&&!C.date(t.value))return;state[field]=t.value;state.page=1;if(field==='unit'){state.department='';state.manager='';}render(); }
    if (t.hasAttribute('data-cx-all')) { state.all=t.checked;state.page=1;render(); }
    if (t.dataset.cxSelect) { if(t.checked)state.selected.add(t.dataset.cxSelect);else state.selected.delete(t.dataset.cxSelect);render(); }
  }
  async function click(event) {
    const t=event.target.closest('button'); if(!t)return;
    if(t.dataset.cxTab){state.tab=t.dataset.cxTab;render();}
    if(t.hasAttribute('data-cx-list'))showPeople();
    if(t.hasAttribute('data-cx-help'))showHelp();
    if(t.hasAttribute('data-cx-quick')){state.timing=t.dataset.cxQuick;state.page=1;showPeople();}
    if(t.hasAttribute('data-cx-clear')){Object.assign(state,{search:'',unit:'',department:'',manager:'',milestone:'',timing:'',operation:'',page:1,all:false});state.selected.clear();render();}
    if(t.dataset.cxPage){state.page+=Number(t.dataset.cxPage);render();}
    if(t.dataset.cxPerson)person(t.dataset.cxPerson);
    if(t.dataset.cxOpenSession)openSession(t.dataset.cxOpenSession);
    if(t.dataset.cxSessionDetail)W.openSession(t.dataset.cxSessionDetail,workflowContext());
    if(t.dataset.cxReport)W.openReport(t.dataset.cxReport,workflowContext());
    if(t.hasAttribute('data-cx-workflow-agenda')){state.tab='sessions';render();}
    if(t.hasAttribute('data-cx-show-sessions')){const list=C.scopeSessions(saved.sessions,model.employees,sharedFilters).matching;const ids=new Set(list.map(s=>s.id));const dates=[...list.flatMap(s=>{const w=C.sessionWindow(s);return [w.start,w.end];}),...saved.executions.filter(e=>ids.has(e.session)).map(e=>e.date),...saved.committees.filter(c=>ids.has(c.session)).map(c=>c.date),...saved.actions.filter(a=>ids.has(a.session)).map(a=>a.due)].filter(C.date).sort();if(dates.length){revealDate(dates[0]);revealDate(dates.at(-1));render();}}
    if(t.hasAttribute('data-cx-suggest'))suggestionForm();
    if(t.hasAttribute('data-cx-new-session'))sessionForm();
    if(t.dataset.cxEditSession)sessionForm(saved.sessions.find(s=>s.id===t.dataset.cxEditSession));
    if(t.dataset.cxAttendance)W.openSession(t.dataset.cxAttendance,workflowContext());
    if(t.dataset.cxCommunication)communication(saved.sessions.find(s=>s.id===t.dataset.cxCommunication));
    if(t.hasAttribute('data-cx-nps-refresh'))refreshNps(true);
    if(t.dataset.cxNps)X.openNps(saved.sessions.find(s=>s.id===t.dataset.cxNps),extraContext());
    if(t.dataset.cxCancel)confirmCancel(t.dataset.cxCancel);
    if(t.hasAttribute('data-cx-new-action'))actionForm();
    if(t.hasAttribute('data-cx-import-pilot'))importPilot();
    if(t.dataset.cxToggleAction&&await save(d=>{const a=d.actions.find(a=>a.id===t.dataset.cxToggleAction);a.done=!a.done;a.completedAt=a.done?new Date().toISOString():null;}))render();
  }
  function showPeople() { state.tab='overview';render();el.querySelector('#cx-people')?.scrollIntoView({block:'start'}); }
  function dialog(title, content) {
    modal?.remove();modal=document.createElement('dialog');modal.className='cx-dialog';modal.setAttribute('aria-label',title);modal.innerHTML=`<div class="cx-row"><h2>${E(title)}</h2><button type="button" class="cx-close" aria-label="Fechar">Fechar ×</button></div>${content}`;document.body.append(modal);const current=modal;let dirty=false;current.addEventListener('input',()=>{dirty=true;});current.addEventListener('change',()=>{dirty=true;});
    current.addEventListener('click',event=>{if(current.hasUnsaved?.()&&event.target.closest('[data-committee-new],[data-committee-open],[data-back-report],[data-return-session],[data-turma-edit],[data-turma-cancel],[data-turma-communication]')){event.preventDefault();event.stopImmediatePropagation();toast('Salve as alterações antes de sair desta seção.');}},true);
    current.hasUnsaved=()=>dirty;current.markTurmaSaved=()=>{dirty=false;};
    function requestClose(){if(!current.hasUnsaved()){current.close();return;}if(current.querySelector('[data-cx-discard]'))return;const warning=document.createElement('div');warning.className='cx-note cx-warning';warning.innerHTML='<strong>Há alterações sem salvar.</strong><p>Você pode continuar editando ou descartar estas alterações.</p><button type="button" class="cx-btn secondary" data-cx-keep>Continuar editando</button> <button type="button" class="cx-btn secondary" data-cx-discard>Descartar e fechar</button>';current.prepend(warning);warning.querySelector('[data-cx-keep]').onclick=()=>warning.remove();warning.querySelector('[data-cx-discard]').onclick=()=>current.close();}
    current.querySelector('.cx-close').onclick=requestClose;current.addEventListener('cancel',event=>{if(current.hasUnsaved()){event.preventDefault();requestClose();}});modal.addEventListener('close',()=>modal.remove(),{once:true});modal.showModal();return modal;
  }
  function showHelp() {
    const c=saved.config, first=c.milestones[0];
    const item=(title,description)=>`<div class="cx-help-item"><strong>${title}</strong><p>${description}</p></div>`;
    const content={
      overview:()=>`${item('Colaboradores no recorte','Conta pessoas distintas com uma etapa atribuída no período e nos filtros do hub.')}${item('Na janela de atendimento','Etapas ainda sem participação cuja janela está aberta na data de hoje. Não indica presença ou ausência em encontros anteriores.')}${item('Próximas etapas','Etapas cuja janela abrirá em até '+c.upcoming+' dias. O cartão abre a lista com esse filtro.')}${item('NPS da jornada','O NPS varia de −100 a +100: percentual de notas 9–10 menos percentual de notas 0–6. A média das notas vai de 0 a 10. Ambos usam somente respostas recebidas, com contagem de respondentes; o período considera a data do encontro, e cada marco reúne as respostas individuais das turmas, sem fazer média dos NPS por turma.')}${item('Distribuições','Mostram quantos elegíveis pertencem a cada marco e operação. A lista abaixo usa os mesmos filtros.')}`,
      people:()=>`${item('Marco e alvo','O marco é contado da admissão deste vínculo. O alvo é o dia exato em que ele completa o marco.')}${item('Na janela / Próximo / Futuro','Na janela comum: hoje está entre '+c.before+' dias antes e '+c.after+' dias depois do alvo. Próximo: a janela começa em até '+c.upcoming+' dias. Futuro: começa mais tarde. Na entrada inicial de 30 dias, quem já passou de 40 dias pode ser atendido até o limite de 140 dias.')}${item('Prazo ultrapassado','A janela calculada terminou sem participação registrada. Isso não comprova falta ao encontro.')}${item('A convocar / Agendado / Realizado / Reagendar','Acompanhamento do próprio Conexão RH: sem turma; turma salva; participação registrada; ou falta registrada que pede novo agendamento.')}${item('Recuperação inicial','Entrada excepcional no marco final para colaboradores que ultrapassaram a janela comum na implantação, respeitado o limite de '+c.maxEligibleAge+' dias.')}${item('Janela prevista e seleção','A janela mostra as datas permitidas para o marco. A caixa na coluna Turma pré-seleciona participantes para montagem manual, sem limitar unidade ou marco. Criar turma manual também permite buscar qualquer vínculo do quadro integrado. A sugestão automática continua aplicando as regras do programa e gera somente uma prévia.')}`,
      sessions:()=>`${item('Como abrir a turma','Clique no título com marco, data e horário. A janela reúne participantes e condução, relatório e devolutiva e NPS do encontro.')}${item('Colunas do Kanban','Agendada: preparação e encontro; Relatório em preparação: execução finalizada aguardando revisão; Aguardando comitê: relatório pronto sem reunião ou com unidades ainda sem comitê; Comitê agendado: há reunião pendente; Devolutiva e ações: comitês realizados, faltando comunicação ou ações; Concluída: comitês realizados, todas as unidades contempladas, devolutivas registradas e ações concluídas.')}${item('Avanço automático','A posição depende dos registros da turma. Finalizar execução, revisar relatório, agendar e concluir comitês, registrar devolutiva e concluir ações atualizam o cartão. Reabrir uma ação devolve o cartão ao acompanhamento.')}${item('Período e filtros','O período inclui o intervalo da criação até o encontro e também datas de execução, comitê ou prazos de ações. Unidade, departamento, gestor e colaborador continuam usando o cadastro integrado. Turmas sem participantes encontrados ficam ocultas.')}${item('NPS','Links individuais são liberados após o horário e a presença. A resposta ao NPS é voluntária e não bloqueia o encerramento operacional da turma.')}${item('Canceladas e ações gerais','Turmas canceladas ficam no histórico recolhido abaixo do quadro. Compromissos gerais de apoio ficam em Ações gerais; compromissos de turma ficam dentro da própria turma.')}`,
      actions:()=>`${item('Relatório de execução','Abra Acessar turma na agenda, conduza o roteiro do marco e finalize o registro de participação e síntese. A execução prepara um relatório coletivo para revisão.')}${item('Comitê de devolutiva','Após revisar o relatório, agende RH/DHO que conduziu o encontro, multiplicadora de T&D da região e gestão regional. Registre decisões, responsáveis e prazos; o convite pode ser baixado para o calendário.')}${item('Devolutiva aos colaboradores','Depois do comitê, registre a comunicação realizada ao grupo. A referência do programa é até 15 dias após o encontro. O módulo não envia mensagens.')}${item('Ação','Compromisso operacional com responsável e prazo, geral ou associado a uma turma.')}${item('Pendente / Concluída','Status controlado no Hub. Concluir e reabrir não atualizam outros sistemas.')}${item('Prazo vencido','Ação pendente cuja data de entrega passou.')}${item('Filtros do hub','O período considera a data de prazo da ação. Unidade, departamento, gestor e colaborador consideram participantes da turma vinculada; ações gerais aparecem no recorte sem esses filtros.')}`,
      settings:()=>`${item('Marcos em dias','Dias de empresa contados desde a admissão do vínculo. O alvo de cada etapa é a admissão somada ao marco.')}${item('Antecipação: '+c.before+' dias','Abre a janela '+c.before+' dias antes da data-alvo.')}${item('Tolerância: '+c.after+' dias','Fecha a janela '+c.after+' dias depois da data-alvo. Não é o prazo para enviar convite.')}${item('Antecedência da lista: '+c.upcoming+' dias','Marca a etapa como “Próximo” até '+c.upcoming+' dias antes de a janela abrir. Não amplia a janela nem impede que etapas futuras apareçam na lista.')}${item('Exemplo: marco de '+first+' dias','Com os valores atuais, “Próximo” pode começar no '+Math.max(0,first-c.before-c.upcoming)+'º dia de empresa; a janela vai do '+(first-c.before)+'º ao '+(first+c.after)+'º dia.')}${item('Limite, capacidade e duração','Limite de elegibilidade: tempo máximo de empresa para entrada no programa. Capacidade: máximo de participantes por turma. Duração: minutos previstos para o encontro.')}${item('Recuperação inicial','Inclui no marco final quem estava além da janela comum na implantação, até o limite de elegibilidade. Alterações nestas regras ficam no Hub.')}`
    };
    const titles={overview:'Acompanhamento',sessions:'Turmas e jornada',actions:'Relatório e Devolutiva',settings:'Regras do programa'};
    dialog('Como ler: '+titles[state.tab],`<div class="cx-help-content">${state.tab==='overview'?content.overview()+content.people():content[state.tab]()}</div>`);
  }
  function person(key) {
    const e=model.employees.find(e=>e.key===key);if(!e){toast('Este vínculo não consta na base do quadro atual. Atualize os dados para conferir.');return;}
    const entry=C.launchQueue(model,{}).queue.find(s=>s.employee.key===key);
    const stages=model.stages.filter(s=>s.employee.key===key),events=saved.events.filter(x=>stages.some(s=>s.key===x.stage));
    const raw=(HUB_DATA.colaboradores||[]).find(r=>String(r.id)===String(e.id)&&C.date(r.data_admissao)===e.admission);
    const allowed=permission=>HUB_PERMISSIONS.hasPerm(HUB_USER,permission);
    const activity=HUB_CONEXAO_PROFILE.personalActivity(e,HUB_DATA.colaboradores||[],allowed('indicadores.feedbacks')?HUB_DATA.feedbacks:[],allowed('indicadores.celebracoes')?HUB_DATA.celebracoes:[]);
    const shortDate=value=>D(value);
    const list=(rows,describe)=>rows.slice(0,4).map(row=>`<li>${shortDate(row.data)} · ${describe(row)}</li>`).join('');
    const anonymous=value=>['sim','true','1','yes'].includes(C.norm(value));
    const feedbackHtml=!allowed('indicadores.feedbacks')?'<p class="cx-muted">Sem permissão para Feedbacks.</p>':activity.ambiguous?'<p class="cx-muted">Não encontrado: o Headcount não permitiu associar o registro nominal a este vínculo.</p>':`<p><strong>${activity.receivedFeedback.length}</strong> recebido(s) · <strong>${activity.sentFeedback.length}</strong> enviado(s)</p>${activity.receivedFeedback.length?`<ul class="cx-profile-list">${list(activity.receivedFeedback,row=>`De ${anonymous(row.anonimo)?'remetente anônimo':E(row.de||'não informado')}${row.avaliacao?' · '+E(row.avaliacao):''}`)}</ul>`:'<p class="cx-muted">Sem registro de feedback nominal recebido.</p>'}<p class="cx-muted">O Hub fornece remetente, destinatário, data e avaliação; o texto do feedback não é carregado nesta tela.</p>`;
    const celebrationHtml=!allowed('indicadores.celebracoes')?'<p class="cx-muted">Sem permissão para Celebrações.</p>':activity.ambiguous?'<p class="cx-muted">Não encontrado: o Headcount não permitiu associar o registro nominal a este vínculo.</p>':`<p><strong>${activity.receivedCelebrations.length}</strong> recebida(s) · <strong>${activity.sentCelebrations.length}</strong> enviada(s)</p>${activity.receivedCelebrations.length?`<ul class="cx-profile-list">${list(activity.receivedCelebrations,row=>`Enviada por ${E(row.colaborador_enviou||'não informado')}`)}</ul>`:'<p class="cx-muted">Sem registro de celebração nominal recebida.</p>'}<p class="cx-muted">Celebrações dirigidas a “todos” não são atribuídas individualmente.</p>`;
    const dataItem=(title,value)=>`<div><span>${title}</span><strong>${E(value||'Não informado')}</strong></div>`;
    const m=dialog('Ficha do colaborador · '+e.name,`<p class="cx-muted">Dados do vínculo integrado ao Hub Sfera · ${E(e.role)} · ${E(e.unit)}</p><div class="cx-profile-data">${dataItem('Cargo',e.role)}${dataItem('Unidade',e.unit)}${dataItem('Departamento / loja',e.department)}${dataItem('Gestor direto',e.manager)}${dataItem('Situação',e.situation)}${dataItem('Admissão',D(e.admission))}${dataItem('Tempo de empresa',e.age+' dias em '+D(state.reference))}<div><span>Contato</span><strong data-cx-contact>Consultando Headcount…</strong></div></div>
      <section class="cx-profile-section"><h3>Jornada no Conexão RH</h3><div class="cx-steps">${stages.map(s=>`<div class="cx-step">${badge(entry&&s.key===entry.key?entry.operation:s.operation,entry&&s.milestone<entry.entryMilestone?'Não previsto na implantação':undefined)}<strong>${s.milestone} dias</strong><span class="cx-muted">Alvo ${D(s.target)}<br>${label[s.timing]}</span><div data-cx-nps-stage="${s.milestone}" data-cx-nps-employee="${E(e.key)}">${X.personal(e.key,s.milestone)}</div></div>`).join('')}</div><p class="cx-muted">${events.length?events.map(x=>`${D(x.date)} · ${x.type==='presente'?'Participou':'Faltou'} no marco ${stages.find(s=>s.key===x.stage)?.milestone} dias`).join('<br>'):'Nenhuma participação registrada no Conexão RH. Isso não confirma ausência em encontros anteriores.'}</p></section>
      <div class="cx-profile-grid"><section class="cx-profile-section"><h3>Feedbacks</h3>${feedbackHtml}</section><section class="cx-profile-section"><h3>Celebrações</h3>${celebrationHtml}</section></div>
      <section class="cx-profile-section"><h3>Avaliação de Experiência</h3><p class="cx-muted">Associação por CPF e data de admissão; resultados de 45 e 90 dias independem do período da barra.</p><div data-cx-ave>Consultando avaliações…</div></section>
      <section class="cx-profile-section"><h3>Humor e contexto do departamento</h3><p class="cx-muted">Departamento atual: ${E(e.department)} · ${E(e.unit)}. A nota de engajamento e o turnover seguem o período do filtro geral; a base mensal de humor usa os meses que cruzam esse período.</p><div data-cx-team>Consultando dados disponíveis…</div></section>
      ${X.fitSection()}<section class="cx-profile-section"><h3>Observações do Conexão</h3><p class="cx-muted">Observações compartilhadas com a equipe autorizada. Registre acompanhamentos objetivos e necessários.</p><form data-cx-observation-form><label class="cx-field">Nova observação<textarea name="text" rows="4" maxlength="2000" required placeholder="Registre um acompanhamento objetivo..."></textarea></label><div class="cx-error" data-cx-observation-error role="alert"></div><button class="cx-btn" type="submit">Salvar observação</button></form><div data-cx-observations></div></section>`);
    m.classList.add('cx-profile-dialog');
    function renderObservations(){const notes=(saved.observations||[]).filter(note=>note.employee===key).slice().reverse();m.querySelector('[data-cx-observations]').innerHTML=notes.length?notes.map(note=>`<article class="cx-observation"><small>${E(new Date(note.created).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))} · ${E(note.author||'Usuário do Conexão RH')}</small><p>${E(note.text)}</p></article>`).join(''):'<p class="cx-muted">Nenhuma observação registrada no Conexão RH.</p>';}
    renderObservations();
    m.querySelector('[data-cx-observation-form]').onsubmit=async event=>{event.preventDefault();const field=event.target.elements.text,text=field.value.trim();if(!text||text.length>2000){m.querySelector('[data-cx-observation-error]').textContent='Escreva uma observação com até 2.000 caracteres.';return;}if(await save(data=>data.observations.push({id:S.id(),employee:key,text,created:new Date().toISOString(),author:HUB_USER.nome||HUB_USER.email||''}))){saved=S.read();field.value='';m.querySelector('[data-cx-observation-error]').textContent='';renderObservations();m.markTurmaSaved?.();toast('Observação salva apenas no Hub.');}};
    async function loadExperience(){const box=m.querySelector('[data-cx-ave]');if(!allowed('indicadores.experiencia')){box.textContent='Seu perfil não tem acesso à Avaliação da Experiência.';return;}if(!raw?.cpf){box.textContent='CPF não disponível para associação segura da avaliação.';return;}const statusLabel=value=>({concluida:'Concluída',pendente:'Pendente',rascunho:'Em preenchimento'}[value]||value||'Não informado');const number=value=>value==null?'—':Number(value).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});try{const results=await Promise.all([45,90].map(async ciclo=>{const rows=await HUB_EXPERIENCIA.carregar(ciclo);const result=HUB_CONEXAO_EXPERIENCIA.summarize(rows,{cpf:raw.cpf,admission:e.admission},ciclo,HUB_EXP_METRICS);if(result.state!=='found'){const message=result.state==='ambiguous'?'Mais de uma avaliação para este vínculo; requer validação.':result.state==='identity'?'Identificação insuficiente para associação segura.':'Nenhuma avaliação acessível para este vínculo.';return `<section class="cx-ave-result"><h4>${ciclo} dias</h4><p class="cx-muted">${message}</p></section>`;}return `<section class="cx-ave-result"><div class="cx-row"><h4>${ciclo} dias</h4>${badge(result.complete?'realizado':'Pendente',result.complete?'Avaliação do gestor concluída':'Resultado ainda não finalizado')}</div><div class="cx-ave-score"><div><span class="cx-muted">Nota final</span><strong>${result.score==null?'—':number(result.score)+' <small>/ 4</small>'}</strong></div><div><span class="cx-muted">Decisão</span><p><strong>${E(result.decision)}</strong></p></div></div><p class="cx-muted">Gestor: ${E(statusLabel(result.managerStatus))} · nota ${number(result.managerScore)} · ${D(result.managerDate)}<br>Autoavaliação: ${E(statusLabel(result.selfStatus))} · nota ${number(result.selfScore)} · ${D(result.selfDate)}</p></section>`;}));if(m.isConnected)box.innerHTML=results.join('');}catch(error){if(m.isConnected)box.textContent='Não foi possível consultar as avaliações: '+error.message;}}
    async function loadContact() {
      const box=m.querySelector('[data-cx-contact]');
      if(!allowed('indicadores.headcount')){box.textContent='Sem permissão';return;}
      try {
        const {data,error}=await sb.from('colaboradores').select('id,cpf,data_admissao,matricula').eq('id',e.id).limit(1);
        if(error)throw error;
        if(!m.isConnected)return;
        const record=data?.[0];
        if(!record || C.date(record.data_admissao)!==e.admission || raw?.cpf && String(record.cpf||'').replace(/\D/g,'')!==String(raw.cpf).replace(/\D/g,'')){box.textContent='Não encontrado';return;}
        box.textContent=String(record.matricula||'').trim()||'Sem registro';
      } catch(error){if(m.isConnected)box.textContent='Não foi possível consultar o contato.';}
    }
    async function loadTeam() {
      const box=m.querySelector('[data-cx-team]');
      const hasBulletin=allowed('indicadores.boletim');
      const hasEngagement=allowed('indicadores.engajamento');
      const hasTurnover=allowed('indicadores.rotatividade');
      const period={start:sharedFilters.start||'2020-01-01',end:sharedFilters.end||C.today()};
      const parts=[];
      parts.push('<p><strong>Histórico de humor individual:</strong> Não disponível nesta integração. O arquivo de origem contém lançamentos por pessoa e dia, mas a tabela atual do Hub preserva apenas o agregado mensal do departamento.</p>');
      if(hasBulletin){
        try {
          await HUB_BOLETIM.carregar();
          if(!m.isConnected)return;
          const mood=HUB_CONEXAO_PROFILE.departmentMood(e,HUB_BOLETIM_DATA.humor_mensal||[],period);
          parts.push(mood
            ? `<p><strong>Média de humor do departamento:</strong> ${mood.average==null?'Não exibida (menos de 3 pessoas)':' '+mood.average.toLocaleString('pt-BR',{maximumFractionDigits:1})+' / 5'} · ${mood.records} registro(s) nos meses do filtro</p>`
            : '<p><strong>Média de humor do departamento:</strong> Sem registro no período.</p>');
          if(hasEngagement){
            const score=HUB_CONEXAO_PROFILE.departmentEngagementScore(e,HUB_BOLETIM_DATA.engajamento_notas||[],period);
            parts.push(score
              ? `<p><strong>Nota de engajamento do departamento:</strong> ${score.average==null?'Não exibida (menos de 3 respondentes)':' '+score.average.toLocaleString('pt-BR',{maximumFractionDigits:2})+' / 5'} · média de todas as respostas do período</p>`
              : '<p><strong>Nota de engajamento do departamento:</strong> Sem registro no período.</p>');
          }else parts.push('<p><strong>Nota de engajamento do departamento:</strong> Sem permissão para consulta.</p>');
        }catch(error){if(!m.isConnected)return;parts.push('<p class="cx-muted">Não foi possível carregar o humor e a nota de engajamento do departamento.</p>');}
      }else parts.push('<p class="cx-muted">Sem permissão para consultar humor e notas agregadas do Boletim.</p>');
      if(hasTurnover){
        try {
          const rot=HUB_METRICS.rotatividadeMetrics({start:period.start,end:period.end,unidade:[e.unit],departamento:[e.department]});
          const hc=rot.serie?.reduce((sum,row)=>sum+(row.headcountInicio||0),0)/(rot.serie?.length||1);
          parts.push(hc>0
            ? `<p><strong>Turnover do departamento:</strong> ${(rot.taxaTurnoverGeral*100).toLocaleString('pt-BR',{maximumFractionDigits:1})}% · ${rot.totalAdmitidos} admissão(ões), ${rot.totalDesligados} desligamento(s) no período</p>`
            : '<p><strong>Turnover do departamento:</strong> Sem base de headcount no período.</p>');
        }catch(error){parts.push('<p class="cx-muted">Não foi possível calcular o turnover do departamento.</p>');}
      }else parts.push('<p><strong>Turnover do departamento:</strong> Sem permissão para consulta.</p>');
      if(m.isConnected)box.innerHTML=parts.join('');
    }
    loadContact();loadExperience();loadTeam();X.bindFit(m,e,raw,toast);refreshNps(true);
  }
  function revealDate(value) {
    let expanded = false;
    for (const [id, shouldExpand] of [['f-start', current => current && value < current], ['f-end', current => current && value > current]]) {
      const input = document.getElementById(id);
      if (input && shouldExpand(input.value)) { input.value = value; input.dispatchEvent(new Event('change', { bubbles: true })); expanded = true; }
    }
    return expanded;
  }
  function openSession(id) {
    const session = saved.sessions.find(s=>s.id===id);
    if (!session) { toast('A turma não está disponível no Hub. Atualize os dados para conferir.'); return; }
    state.focusSession = id;
    state.tab = 'sessions';
    const expanded = C.sessionInPeriod(session,sharedFilters) ? false : revealDate(C.sessionWindow(session).start);
    render();
    el.querySelectorAll('[data-cx-session-id]').forEach(node=>{if(node.dataset.cxSessionId===id)node.scrollIntoView({block:'center'});});
    if (expanded) toast('Período ampliado para exibir a turma vinculada. Nenhum convite foi enviado automaticamente.');
    W.openSession(id,workflowContext());
  }
  function suggestionForm(previous) {
    rebuild();
    const selected=state.selected.size>0;
    const source=selected?scopeStages().filter(s=>state.selected.has(s.key)):filtered();
    if(!source.length){toast('Nenhum elegível no recorte atual. Revise os filtros para sugerir turmas.');return;}
    const suggestionLastStart=String(Math.floor((16*60-saved.config.duration)/60)).padStart(2,'0')+':'+String((16*60-saved.config.duration)%60).padStart(2,'0');
    const m=dialog('Sugestão de formação de turmas',`<p class="cx-muted">${source.length} colaboradores na ${selected?'seleção atual':'lista filtrada'}. A prévia usa os dados integrados ao hub e não salva agendamentos.</p><form data-suggestion-form><div class="cx-toolbar"><label class="cx-field">Data preferencial inicial<input name="startDate" type="date" value="${C.add(C.today(),7)}" min="${C.today()}" required></label><label class="cx-field">Primeiro horário do dia<input name="startTime" type="time" value="10:00" min="10:00" max="${suggestionLastStart}" required></label></div><label class="cx-field">Facilitador das turmas<input name="facilitator" value="${E(HUB_USER.nome||'')}" maxlength="100" required></label><div class="cx-toolbar"><label class="cx-field">Máximo por loja na mesma turma<input name="maxPerStore" type="number" value="${saved.config.capacity}" min="1" max="${saved.config.capacity}" required></label><label class="cx-field">Turmas por dia do facilitador<input name="maxPerDay" type="number" value="4" min="1" max="8" required></label><label class="cx-field">Horizonte a partir da data preferencial (dias)<input name="horizon" type="number" value="21" min="1" max="60" required></label></div><label class="cx-muted"><input name="allowUrgent" type="checkbox" checked> Incluir urgentes antes da data preferencial, a partir de hoje</label><p class="cx-muted">Turmas equilibradas por marco e unidade; colaboradores VD podem participar juntos. No marco de 30 dias, a entrada inicial de quem já passou de 40 dias fica em turmas próprias, separadas de quem está na janela comum de 20 a 40 dias. O limite por loja começa na capacidade da turma e pode ser reduzido se a operação precisar. Dias úteis de segunda a sexta, com encontros inteiros entre 10h e 16h. Capacidade ${saved.config.capacity}, duração ${saved.config.duration} minutos e intervalo de 15 minutos. Feriados e escalas das lojas precisam de conferência. Prioridade para quem está mais perto do fim da janela; quem já tem turma fica fora de novas sugestões.</p><div class="cx-error" data-suggestion-error role="alert"></div><button class="cx-btn" type="submit">Gerar sugestões</button></form><div data-suggestion-results aria-live="polite"></div>`);
    const form=m.querySelector('form'),box=m.querySelector('[data-suggestion-results]');
    let result=previous?.result||null;
    if(previous){
      for(const input of form.elements){
        if(!input.name)continue;
        if(input.type==='checkbox')input.checked=previous.values.has(input.name);
        else if(previous.values.has(input.name))input.value=previous.values.get(input.name);
      }
      box.innerHTML=previous.html;
      m.scrollTop=previous.scrollTop;
    }
    form.oninput=()=>{result=null;box.innerHTML='';};
    form.onsubmit=async event=>{
      event.preventDefault();m.querySelector('[data-suggestion-error]').textContent='';
      const f=new FormData(form);
      try {
        rebuild();
        const current=C.launchQueue(model,sharedFilters).queue;
        const keys=new Set(source.map(s=>s.key));
        result=G.generate(model,current.filter(s=>keys.has(s.key)),{startDate:f.get('startDate'),startTime:f.get('startTime'),minTimeToday:currentTime(),facilitator:f.get('facilitator'),maxPerStore:+f.get('maxPerStore'),maxPerDay:+f.get('maxPerDay'),horizon:+f.get('horizon'),allowUrgent:f.has('allowUrgent')});
        const count=result.proposals.reduce((total,p)=>total+p.participants.length,0);
        box.innerHTML=`<h3 style="margin-top:24px">${result.proposals.length} turmas sugeridas · ${count} participantes</h3><p class="cx-muted">Nenhuma turma salva. Revise uma sugestão para confirmar data, participantes e liberação das lojas antes de salvar.</p>${result.proposals.map((p,index)=>`<article class="cx-session"><div class="cx-row"><h3>${p.milestone} dias · ${D(p.date)} às ${E(p.time)}</h3>${badge('proximo',p.participants.length+'/'+saved.config.capacity+' participantes')}</div><p class="cx-muted">${E(p.groupLabel)} · ${E(p.facilitator)} · ${p.duration} minutos${p.beforePreferred?' · Antecipada para preservar a janela':''}</p>${p.shortNotice?'<div class="cx-note cx-warning">Menos de sete dias de antecedência: confirmar liberação com a liderança antes de salvar.</div>':''}<p>${p.participants.map(k=>{const e=model.employees.find(e=>e.key===k);return E(e.name)+' · '+E(e.department);}).join('<br>')}</p><button class="cx-btn secondary" data-review-suggestion="${index}">Revisar esta turma</button></article>`).join('')}${result.skipped.length?`<details style="margin-top:20px"><summary>${result.skipped.length} colaboradores sem sugestão · consultar motivos</summary>${result.skipped.map(s=>`<p><strong>${E(s.employee.name)}</strong> · ${s.milestone} dias<br><span class="cx-muted">${E(s.reason)}</span></p>`).join('')}</details>`:''}`;
      } catch(error){result=null;box.innerHTML='';m.querySelector('[data-suggestion-error]').textContent=error.message;}
    };
    box.onclick=async event=>{
      const button=event.target.closest('[data-review-suggestion]');if(!button||!result)return;
      const proposal=result.proposals[+button.dataset.reviewSuggestion];
      rebuild();const errors=G.validate([proposal],model);
      if(errors.length){m.querySelector('[data-suggestion-error]').textContent=errors.join(' ');return;}
      sessionForm(null,proposal,()=>suggestionForm({values:new FormData(form),result,html:box.innerHTML,scrollTop:m.scrollTop}));
    };
  }
  function sessionForm(existing, suggestion, onBack) {
    if(existing&&saved.events.some(event=>event.session===existing.id&&event.type==='presente')){toast('Esta turma já tem participação registrada. Preserve o encontro e seu NPS; crie outra turma para um novo encontro.');return;}
    const draft=existing||suggestion;
    const selected=model.stages.filter(s=>state.selected.has(s.key));
    const milestone=draft?.milestone||selected[0]?.milestone||saved.config.milestones[0];
    const participants=draft?.participants||[...new Set(selected.map(s=>s.employee.key))];
    const scopedKeys=new Set(scopeStages().map(s=>s.key));
    const firstParticipant=model.employees.find(e=>e.key===participants[0]);
    const candidates=suggestion
      ? model.stages.filter(s=>(scopedKeys.has(s.key)||participants.includes(s.employee.key))&&s.employee.age<=saved.config.maxEligibleAge&&s.milestone===milestone&&s.employee.available&&!s.completed&&!s.scheduled&&(s.inCycle||participants.includes(s.employee.key))&&(!firstParticipant||G.groupKey(s.employee)===G.groupKey(firstParticipant))).map(s=>s.employee)
      : [...model.employees].sort((a,b)=>Number(participants.includes(b.key))-Number(participants.includes(a.key))||a.name.localeCompare(b.name,'pt-BR'));
    const milestoneField=!draft?`<label class="cx-field">Marco da turma<select name="milestone">${saved.config.milestones.map(n=>option(n,n+' dias',milestone)).join('')}</select></label>`:'';
    const manualNote=suggestion?'':`<div class="cx-note">Montagem manual: você pode combinar colaboradores de qualquer unidade, marca ou tempo de empresa. Escolha o marco da turma e confirme a disponibilidade e a liberação de cada pessoa. A sugestão automática continua seguindo os critérios do programa.</div>`;
    const search=suggestion?'':`<label class="cx-field">Buscar participante na base integrada<input type="search" data-cx-participant-search placeholder="Nome, unidade ou loja"></label>`;
    const m=dialog(existing?'Editar turma':suggestion?'Revisar turma sugerida':'Criar turma',`${onBack?'<button type="button" class="cx-btn secondary" data-back-suggestions>← Voltar às sugestões</button>':''}<p class="cx-muted">Marco ${milestone} dias · capacidade ${saved.config.capacity}. Encontros das 10h às 16h; convites devem ser organizados com sete dias de antecedência.</p>${manualNote}<form data-session-form>${milestoneField}<div class="cx-toolbar"><label class="cx-field">Data<input name="date" type="date" value="${draft?.date||C.add(C.today(),7)}" min="${C.today()}" required></label><label class="cx-field">Horário<input name="time" type="time" value="${draft?.time||'10:00'}" min="10:00" max="15:45" required></label><label class="cx-field">Duração em minutos<input name="duration" type="number" value="${draft?.duration||saved.config.duration}" min="15" max="180" required></label></div><div class="cx-toolbar"><label class="cx-field">Facilitador<input name="facilitator" value="${E(draft?.facilitator||HUB_USER.nome||'')}" maxlength="100" required></label><label class="cx-field">Modalidade<select name="mode">${['Online','Presencial','Híbrido'].map(v=>option(v,v,draft?.mode||'Online')).join('')}</select></label></div><label class="cx-field">Link da reunião (opcional)<input name="link" type="url" placeholder="https://…" value="${E(draft?.link||'')}" maxlength="1000"></label><h3>Participantes</h3>${search}<div class="cx-checklist">${candidates.map(e=>`<label data-cx-participant-label data-search="${E(C.norm(e.name+' '+e.unit+' '+e.department))}"><input type="checkbox" name="participant" value="${E(e.key)}" ${participants.includes(e.key)?'checked':''}>${E(e.name)} · ${E(e.unit)} · ${E(e.department)}${!e.available?' · Desativado no hub':''}</label>`).join('')}</div><div class="cx-note" data-logistics></div><div class="cx-error" data-form-error role="alert"></div><button class="cx-btn" type="submit">Salvar turma no Hub</button></form>`);
    if(onBack)m.querySelector('[data-back-suggestions]').onclick=onBack;
    const form=m.querySelector('form');
    const participantSearch=m.querySelector('[data-cx-participant-search]');
    if(participantSearch)participantSearch.oninput=()=>{const query=C.norm(participantSearch.value);m.querySelectorAll('[data-cx-participant-label]').forEach(label=>{label.hidden=!!query&&!label.dataset.search.includes(query);});};
    function logistics(){const keys=[...new FormData(form).getAll('participant')];const counts={};keys.forEach(k=>{const e=model.employees.find(e=>e.key===k);if(e)counts[e.department]=(counts[e.department]||0)+1;});const repeat=Object.entries(counts).filter(([,n])=>n>1);m.querySelector('[data-logistics]').textContent=`${keys.length} participantes selecionados de ${saved.config.capacity} vagas. `+(repeat.length?'Conferir liberação simultânea: '+repeat.map(([d,n])=>d+' ('+n+')').join(', '):'Confirme equipamentos, espaço reservado e liberação das lojas.');}form.onchange=logistics;logistics();if(suggestion&&suggestion.shortNotice){const warning=document.createElement('div');warning.className='cx-note cx-warning';warning.textContent='Sugestão com menos de sete dias de antecedência. Confirme a liberação com a liderança antes de salvar.';form.prepend(warning);}
    form.onsubmit=async event=>{event.preventDefault();const f=new FormData(form),s={id:existing?.id||S.id(),milestone:!draft?+f.get('milestone'):milestone,date:f.get('date'),time:f.get('time'),duration:+f.get('duration'),facilitator:f.get('facilitator').trim(),mode:f.get('mode'),link:f.get('link').trim(),participants:f.getAll('participant'),created:existing?.created||new Date().toISOString(),communications:existing?.communications||{},revisions:existing?.revisions||[],source:existing?.source||(suggestion?'suggested':'manual')};s.initialThirty=!!(suggestion?.initialThirty||existing?.initialThirty);const errors=C.sessionConflicts(s,saved.sessions,saved.config,model.employees,{manual:!suggestion});if(suggestion){const first=model.employees.find(e=>e.key===s.participants[0]);if(first&&!G.sameGroup(s.participants,first,model.employees))errors.push('A sugestão não pode misturar unidades diferentes; colaboradores VD podem participar juntos.');errors.push(...G.validate([s],model));if(s.date===C.today()&&s.time<=currentTime())errors.push('Escolha um horário futuro para a turma sugerida.');}if(s.date<C.today())errors.push('Use uma data atual ou futura para agendar.');if(errors.length){m.querySelector('[data-form-error]').textContent=[...new Set(errors)].join(' ');return;}if(await save(d=>{if(existing){const index=d.sessions.findIndex(x=>x.id===existing.id);s.revisions=[...s.revisions,{date:existing.date,time:existing.time,participants:existing.participants,changedAt:new Date().toISOString()}];d.sessions[index]=s;}else d.sessions.push(s);})){state.selected.clear();state.tab='sessions';m.close();const expanded=C.sessionInPeriod(s,sharedFilters)?false:revealDate(C.sessionWindow(s).start);render();toast('Turma salva no Hub. Nenhum convite foi enviado.'+(expanded?' Período da barra ampliado para exibir a turma.':''));}};
  }
  function attendance(session) {
    if(session.date>C.today()){toast('A participação só pode ser registrada na data do encontro ou depois.');return;}
    const m=dialog('Registrar participação',`<p class="cx-muted">${D(session.date)} · marco ${session.milestone} dias. Informe apenas participações que ocorreram no teste. A realização fica registrada no Hub.</p><form>${session.participants.map(k=>`<label class="cx-field">${E(model.employees.find(e=>e.key===k)?.name||'Vínculo fora da base atual')}<select name="${E(k)}">${option('','Não registrar','')}${option('presente','Participou','')}${option('faltou','Faltou','')}</select></label>`).join('')}<div class="cx-error" role="alert"></div><button type="submit" class="cx-btn">Salvar participação</button></form>`);
    m.querySelector('form').onsubmit=async event=>{event.preventDefault();const entries=[...new FormData(event.target)].filter(([,v])=>v);if(!entries.length){m.querySelector('.cx-error').textContent='Informe ao menos uma participação.';return;}if(await save(d=>{for(const [k,type]of entries)d.events.push({id:S.id(),session:session.id,stage:k+':'+session.milestone,type,date:session.date,created:new Date().toISOString()});})){m.close();render();toast('Participação registrada apenas no Conexão RH.');}};
  }
  function communication(session) {
    const m=dialog('Convite e devolutiva',`<p class="cx-muted">Os modelos abaixo são preparação. O módulo não envia mensagens. Após registrar presença, use NPS do encontro para copiar os links individuais.</p><div class="cx-note"><strong>Modelo de convite</strong><br>Você está convidado(a) para o Conexão RH de ${session.milestone} dias, em ${D(session.date)}, às ${E(session.time)}, com duração de ${session.duration} minutos. Confirme sua participação e alinhe a liberação com sua liderança. ${session.link?'Link: '+E(session.link):'O RH informará as instruções de acesso.'}</div><p>Síntese prevista: <strong>${D(C.add(session.date,2))}</strong><br>Devolutiva prevista: <strong>${D(C.add(session.date,15))}</strong></p><p class="cx-muted">A data da síntese é uma referência de dois dias corridos; conferir o prazo exato de 48h a partir do horário do encontro. Registre abaixo somente comunicações efetivamente realizadas.</p><form>${[['invite','Convite realizado'],['summary','Síntese realizada'],['feedback','Devolutiva realizada']].map(([k,t])=>`<label class="cx-field">${t}<input type="date" name="${k}" max="${C.today()}" value="${E(session.communications?.[k]||'')}"></label>`).join('')}<div class="cx-error" role="alert"></div><button class="cx-btn" type="submit">Salvar controle</button></form>`);
    m.querySelector('form').onsubmit=async event=>{event.preventDefault();const comm=Object.fromEntries(new FormData(event.target));if(Object.entries(comm).some(([k,v])=>v&&(!C.date(v)||v>C.today()||(['summary','feedback'].includes(k)&&v<session.date)))){m.querySelector('.cx-error').textContent='Revise as datas: síntese e devolutiva devem ocorrer a partir do encontro, sem datas futuras.';return;}if(await save(d=>{d.sessions.find(s=>s.id===session.id).communications=comm;})){m.close();render();toast('Controle de comunicação atualizado no Hub.');}};
  }
  function confirmCancel(id) {if(S.read().executions.some(e=>e.session===id&&e.status==='final')){toast('Uma turma com execução finalizada não pode ser cancelada.');return;}const m=dialog('Cancelar turma','<p>O cancelamento preserva a turma e seu histórico. As etapas ainda não realizadas voltam a ficar disponíveis para agendamento.</p><button class="cx-btn" data-confirm>Confirmar cancelamento</button>');m.querySelector('[data-confirm]').onclick=async ()=>{if(await save(d=>{d.sessions.find(s=>s.id===id).cancelled=new Date().toISOString();})){m.close();render();}};}
  function actionForm() {
    const m=dialog('Nova ação de acompanhamento',`<p class="cx-muted">Registre compromissos operacionais. Não inclua relatos pessoais, dados de saúde ou denúncias no Conexão RH.</p><form><label class="cx-field">Ação<input name="title" maxlength="180" required placeholder="Ex.: validar equipamentos para a próxima turma"></label><label class="cx-field">Responsável<input name="owner" maxlength="100" required></label><label class="cx-field">Prazo<input type="date" name="due" value="${C.add(C.today(),15)}" required></label><label class="cx-field">Turma de origem<select name="session">${option('','Ação geral','')}${saved.sessions.map(s=>option(s.id,D(s.date)+' · '+s.milestone+' dias','')).join('')}</select></label><div class="cx-error" role="alert"></div><button class="cx-btn" type="submit">Salvar ação</button></form>`);
    m.querySelector('form').onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));if(!data.title.trim()||!data.owner.trim()||!C.date(data.due)){m.querySelector('.cx-error').textContent='Preencha ação, responsável e uma data válida.';return;}if(await save(d=>d.actions.push({...data,title:data.title.trim(),owner:data.owner.trim(),id:S.id(),created:new Date().toISOString(),done:false}))){m.close();const expanded=revealDate(data.due);render();toast('Ação salva no Hub.'+(expanded?' Período da barra ampliado para exibir o prazo.':''));}};
  }
  document.addEventListener('submit',async event=>{if(!event.target.matches('[data-cx-settings]'))return;event.preventDefault();const f=new FormData(event.target),config={launchDate:f.get('launchDate'),initialRecovery:f.has('initialRecovery'),horizon:saved.config.horizon,milestones:String(f.get('milestones')).split(',').map(v=>Number(v.trim()))};for(const key of ['before','after','upcoming','maxEligibleAge','capacity','duration'])config[key]=Number(f.get(key));try{C.settings(config);if(await save(d=>{d.config=config;})){state.selected.clear();render();toast('Regras atualizadas.');}}catch(error){event.target.querySelector('[data-cx-settings-error]').textContent=error.message;}});

  function importPilot(){
    const m=dialog('Importar turmas do piloto','<p>Selecione o backup JSON exportado no laboratório. Escolha somente turmas reais. Esta importação preserva os identificadores e não substitui registros já publicados. PDFs devem ser anexados novamente na ficha.</p><label class="cx-field">Backup do laboratório<input type="file" accept="application/json,.json" data-pilot-file></label><div data-pilot-preview></div>');
    const input=m.querySelector('[data-pilot-file]'),box=m.querySelector('[data-pilot-preview]');let source;
    input.onchange=async()=>{try{const f=input.files[0];if(!f||f.size>8000000)throw Error('Use um backup JSON de até 8 MB.');source=JSON.parse(await f.text());if(source.version!==1||!Array.isArray(source.sessions))throw Error('Backup incompatível.');
      const known=new Set(model.employees.map(e=>e.key)),existing=new Set(S.read().sessions.map(s=>s.id));const sessions=source.sessions.filter(s=>!existing.has(s.id)&&Array.isArray(s.participants)&&s.participants.length&&s.participants.every(k=>known.has(k)));
      box.innerHTML='<form data-pilot-confirm><h3>'+sessions.length+' turmas com participantes encontrados</h3>'+sessions.map(s=>'<label class="cx-field"><span><input type="checkbox" name="session" value="'+E(s.id)+'"> '+s.milestone+' dias · '+D(s.date)+' às '+E(s.time)+' · '+s.participants.length+' participantes</span></label>').join('')+'<label class="cx-field"><span><input type="checkbox" name="real" required> Conferi e selecionei somente registros reais para a operação.</span></label><p class="cx-error" role="alert"></p><button class="cx-btn">Importar turmas selecionadas</button></form>';
      box.querySelector('form').onsubmit=async event=>{event.preventDefault();const values=new FormData(event.target),ids=new Set(values.getAll('session'));if(!ids.size){box.querySelector('.cx-error').textContent='Selecione pelo menos uma turma real.';return;}
        if(await save(state=>{for(const kind of ['sessions','events','executions','reports','committees','actions']){for(const record of source[kind]||[]){if(!ids.has(kind==='sessions'?record.id:record.session))continue;const id=kind==='executions'?record.session:record.id;if(!state[kind].some(r=>(kind==='executions'?r.session:r.id)===id))state[kind].push({...record,...(kind==='sessions'?{importedPilot:true}:{})});}}})){m.markTurmaSaved?.();m.close();state.tab='sessions';render();toast('Turmas selecionadas importadas. Confira a jornada antes de continuar.');}
      };
    }catch(error){box.textContent=error.message;}};
  }

  window.HUB_CONEXAO = { render };
  window.addEventListener('focus',()=>{if(el&&canRead())refreshNps(true);});
  if(typeof BroadcastChannel==='function'){const channel=new BroadcastChannel('sfera-conexao-nps');channel.onmessage=()=>{if(el&&canRead())refreshNps(true);};}
})();
